using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class CrashCheckTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
 static int Different(D.Bitmap a,D.Bitmap b){int count=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))count++;return count;}


 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("任务栏外观");Click(w,"显示内容");var gpu=Named<CheckBox>(w,"显示项目-gpu");gpu.IsChecked=true;gpu.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Named<Button>(w,"上移-gpu").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Click(w,"布局与屏幕");var column=(Grid)Named<TextBox>(w,"第2列数值宽度").Parent;Check(((TextBlock)column.Children[0]).Text=="第2列"&&Convert.ToString(((TextBlock)column.Children[0]).ToolTip).Contains("GPU"),"column contents follow display selection and reorder");Named<ComboBox>(w,"排列方式").SelectedIndex=1;Check(((TextBlock)column.Children[0]).Text=="第2列"&&Convert.ToString(((TextBlock)column.Children[0]).ToolTip).Contains("↑"),"column contents follow explicit single-row layout");Named<ComboBox>(w,"排列方式").SelectedIndex=0;var autofit=Named<CheckBox>(w,"自动缩放至可用宽高（最小7pt）");autofit.IsChecked=false;autofit.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));var autorows=Named<CheckBox>(w,"根据任务栏高度自动切换单/双行");autorows.IsChecked=true;autorows.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Click(w,"配色与文字");Named<TextBox>(w,"中文字号（7–24 pt）").Text="24";Named<TextBox>(w,"英文字号（7–24 pt）").Text="24";Click(w,"布局与屏幕");var draft=(MonitorConfig)Get(w,"taskbarDraft");int actualRows=TaskbarPainter.Geometry(draft,1,TaskbarMonitor.HeightInDips(draft.TaskbarScreen)).Rows;int visible=Enumerable.Range(1,10).Select(n=>Named<TextBox>(w,"第"+n+"列数值宽度")).Count(box=>((FrameworkElement)box.Parent).Visibility==Visibility.Visible);Check(actualRows==1&&visible==draft.TaskbarItems.Count,"column editors follow automatic row fallback");Shot(w,Path.Combine(args[0],"column-labels.png"));
 string logDir=Path.Combine(args[0],"diagnostic-fixture");string log=CrashDiagnostics.Record(new InvalidOperationException("test diagnostic marker"),"test context",logDir);Check(File.Exists(log)&&File.ReadAllText(log).Contains("test diagnostic marker")&&File.ReadAllText(log).Contains(CrashDiagnostics.Version),"diagnostics records local version context and error");for(int i=0;i<11;i++)CrashDiagnostics.Record(new Exception("test"),"rotation",logDir);Check(Directory.GetFiles(logDir,"crash-*.log").Length==10,"diagnostics bounds storage to ten owned logs");string blocked=Path.Combine(args[0],"not-a-directory");File.WriteAllText(blocked,"test");Check(CrashDiagnostics.Record(new Exception("test"),"write failure",blocked)=="","diagnostic I/O failure cannot replace original error");
 CrashDiagnostics.Install(app);bool unhandledBeforeTest=false;app.DispatcherUnhandledException+=(sender,eventArgs)=>{if(eventArgs.Exception is InvalidOperationException&&eventArgs.Exception.Message=="dispatcher diagnostic probe"){unhandledBeforeTest=!eventArgs.Handled;eventArgs.Handled=true;}};app.Dispatcher.BeginInvoke(new Action(()=>{throw new InvalidOperationException("dispatcher diagnostic probe");}));Pump();string errors=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"errors");Check(Directory.Exists(errors)&&Directory.GetFiles(errors,"crash-*.log").Any(file=>File.ReadAllText(file).Contains("dispatcher diagnostic probe")),"real dispatcher exception reaches local diagnostic log");Check(unhandledBeforeTest,"production diagnostics does not suppress dispatcher failures");
 foreach(string page in new[]{"健康","提醒","进程监控","Codex状态","快捷入口","气泡外观","任务栏外观"}){w.ShowPage(page);Pump();w.Close();Call(pet,"OpenTerminal");w=(TerminalWindow)Get(pet,"terminal");w.ShowPage(page);Pump();Check(w.IsVisible,"latest console reopens "+page);} 
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"crash-check-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true}));return failures==0?0:1;}
}
